{
  "analysis": "Style.css created. Now we need to create the visualization.js file. This is the most complex part. We'll write the D3 code to load the CSV, create the bubble chart with force simulation, sector clustering, tooltips, and the linked table. We'll also format market cap as T, B, etc. We'll ensure determinism by sorting data and using fixed simulation parameters.",
  "plan": "Create visualization.js in /root/output/js/. We'll write the code step by step via a heredoc. After creating the file, we can optionally test by opening the HTML in a browser (but we don't have a browser installed; we can just verify the file exists).",
  "commands": [
    {
      "keystrokes": "cat > js/visualization.js << 'EOF'
// Stock Visualization with D3 v6
// Deterministic: sort data, fixed seed, no randomness

// Dimensions
const width = 900;
const height = 500;

// Tooltip
const tooltip = d3.select("body").append("div")
    .attr("class", "tooltip")
    .style("opacity", 0);

// Load data
d3.csv("/root/output/data/stock-descriptions.csv").then(data => {
    // Convert numeric columns
    data.forEach(d => {
        d.marketCap = +d.marketCap;
        // If marketCap is missing or not a number (ETFs), set to 0
        if (isNaN(d.marketCap) || d.marketCap <= 0) {
            d.marketCap = 0;
        }
    });

    // Sort by ticker for determinism
    data.sort((a, b) => d3.ascending(a.ticker, b.ticker));

    // Sector colors
    const sectors = [...new Set(data.map(d => d.sector))].sort();
    const color = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeSet2);

    // Size scale for bubbles (area proportional to marketCap)
    const maxCap = d3.max(data, d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxCap])
        .range([5, 30]); // min and max radius

    // Create SVG
    const svg = d3.select(".chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .style("border", "1px solid #ddd");

    // Create a group for bubbles
    const g = svg.append("g");

    // Force simulation
    const simulation = d3.forceSimulation(data)
        .force("x", d3.forceX().strength(0.05))
        .force("y", d3.forceY().strength(0.05))
        .force("collide", d3.forceCollide().radius(d => radiusScale(d.marketCap) + 2).iterations(4))
        .force("charge", d3.forceManyBody().strength(-20))
        .on("tick", ticked);

    // Sector centers for clustering
    const sectorCenters = {};
    sectors.forEach((sector, i) => {
        // Distribute sectors evenly around a circle
        const angle = (i / sectors.length) * 2 * Math.PI;
        const radius = 150;
        sectorCenters[sector] = {
            x: width / 2 + radius * Math.cos(angle),
            y: height / 2 + radius * Math.sin(angle)
        };
    });

    // Add sector forces
    simulation.force("sectorX", d3.forceX().x(d => sectorCenters[d.sector].x).strength(0.5))
        .force("sectorY", d3.forceY().y(d => sectorCenters[d.sector].y).strength(0.5));

    // Create bubble elements
    const bubbles = g.selectAll(".bubble")
        .data(data)
        .enter().append("g")
        .attr("class", "bubble")
        .call(d3.drag()
            .on("start", dragstarted)
            .on("drag", dragged)
            .on("end", dragended));

    bubbles.append("circle")
        .attr("r", d => d.marketCap > 0 ? radiusScale(d.marketCap) : 12)
        .attr("fill", d => color(d.sector))
        .attr("stroke", "#fff")
        .attr("stroke-width", 1.5)
        .on("mouseover", (event, d) => {
            if (d.marketCap > 0) { // ETFs have no tooltip
                tooltip.style("opacity", 1)
                    .html(`<strong>${d.ticker}</strong><br>${d["full name"]}<br>Sector: ${d.sector}`)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 28) + "px");
            }
        })
        .on("mouseout", () => tooltip.style("opacity", 0))
        .on("click", (event, d) => {
            // Highlight bubble (already done via table click? we'll toggle)
            d3.select(event.currentTarget).classed("selected", true);
            // Highlight table row
            d3.select(`#stock-table tbody tr[data-ticker="${d.ticker}"]`)
                .classed("active", true)
                .each(function() { this.scrollIntoView({block: "nearest"}); });
        });

    bubbles.append("text")
        .attr("class", "label")
        .attr("text-anchor", "middle")
        .attr("dy", ".2em")
        .text(d => d.ticker);

    // Add legend
    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", `translate(20, ${height - 20})`);

    sectors.forEach((sector, i) => {
        const legendRow = legend.append("g")
            .attr("transform", `translate(${i * 120}, 0)`);
        legendRow.append("circle")
            .attr("r", 6)
            .attr("fill", color(sector));
        legendRow.append("text")
            .attr("x", 10)
            .attr("y", 4)
            .attr("alignment-baseline", "middle")
            .text(sector);
    });

    // Tick function for simulation
    function ticked() {
        bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
    }

    // Drag functions
    function dragstarted(event, d) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
    }

    function dragged(event, d) {
        d.fx = event.x;
        d.fy = event.y;
    }

    function dragended(event, d) {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
    }

    // Create table
    const tableBody = d3.select("#stock-table tbody");

    data.forEach(d => {
        const row = tableBody.append("tr")
            .attr("data-ticker", d.ticker)
            .on("click", () => {
                // Highlight row
                d3.selectAll("#stock-table tbody tr").classed("active", false);
                d3.select(event.currentTarget).classed("active", true);
                // Highlight bubble
                d3.selectAll(".bubble").classed("selected", false);
                d3.selectAll(`.bubble`).filter(b => b.ticker === d.ticker).classed("selected", true);
                // Optionally bubble to front?
            });

        row.append("td").text(d.ticker);
        row.append("td").text(d["full name"]);
        row.append("td").text(d.sector);
        const marketCapCell = row.append("td");
        if (d.marketCap > 0) {
            // Format market cap
            const format = d3.formatPrefix(".1f", 1e-12); // for trillions
            if (d.marketCap >= 1e12) {
                marketCapCell.text(format(d.marketCap) + "T");
            } else if (d.marketCap >= 1e9) {
                marketCapCell.text(d3.formatPrefix(".1f", 1e-9)(d.marketCap) + "B");
            } else if (d.marketCap >= 1e6) {
                marketCapCell.text(d3.formatPrefix(".1f", 1e-6)(d.marketCap) + "M");
            } else {
                marketCapCell.text(d3.format(",.0f")(d.marketCap));
            }
        } else {
            marketCapCell.text("N/A (ETF)");
        }
    });

    // Initial highlight: none
}).catch(error => {
    console.error("Error loading data:", error);
});
EOF
